{
  "name": "opencode-marginalia",
  "version": "0.1.1",
  "description": "Persistent, path-scoped memory for opencode agents. Markdown files, git-backed, no vector database.",
  "type": "module",
  "exports": {
    ".": "./src/index.js",
    "./server": "./src/index.js",
    "./tui": "./src/tui.js"
  },
  "main": "./src/index.js",
  "bin": {
    "marginalia": "./src/cli.js"
  },
  "files": [
    "src",
    "server.js",
    "tui.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc -p tsconfig.json"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.3.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.0",
    "@types/bun": "^1.3.14",
    "typescript": "^7.0.2"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "agent-memory",
    "persistent-memory"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lsequeiraa/marginalia.git"
  },
  "homepage": "https://github.com/lsequeiraa/marginalia#readme",
  "bugs": {
    "url": "https://github.com/lsequeiraa/marginalia/issues"
  },
  "author": "Luís Sequeira",
  "license": "MIT"
}
